//! A client of [Omnigent](https://github.com/omnigent-ai/omnigent)'s REST API, pinned to
//! v0.23.0.
//!
//! The request/response calls are generated by trestle from the hand-written `omnigent.v1`
//! protos in `proto/` (`just omnigent-codegen`, output in `src/gen/`). Three things are
//! written by hand here, because trestle can't generate them:
//!
//! - the SSE stream of a session ([`OmnigentClient::stream`], [`sse`]), which trestle would
//!   buffer whole;
//! - the typed [`Event`]s of that stream ([`events`]);
//! - the fold of events, or of a session snapshot, into chat [`Message`]s ([`fold`]), a port
//!   of the Python SDK's block stream (`omnigent_client/_stream.py`).
//!
//! The transport and base URL are the caller's: [`OmnigentClient::new`] takes a
//! `reqwest::Client` and the server's root (with any gateway prefix, e.g.
//! `http://localhost:8080/omnigent/`). The transport has no retries: a retried
//! `POST …/events` would send a message twice.
//!
//! ```no_run
//! # async fn demo() -> omnigent_client::Result<()> {
//! use futures::StreamExt as _;
//! use omnigent_client::{Conversation, OmnigentClient};
//!
//! let client = OmnigentClient::new(reqwest::Client::new(), "http://localhost:6767/".parse()?);
//! let session = client.create_session("agent_123", |_| {}).await?;
//! // The stream has no replay: open it before sending.
//! let mut events = client.stream(&session.id).await?;
//! client.send_message(&session.id, "hello").await?;
//! let mut conversation = Conversation::default();
//! while let Some(event) = events.next().await {
//!     conversation.apply(&event?);
//! }
//! # Ok(())
//! # }
//! ```

#[allow(missing_docs)]
#[path = "gen/models/mod.rs"]
pub mod models;

#[allow(missing_docs, clippy::all)]
#[path = "gen/codegen/mod.rs"]
mod codegen;

pub mod events;
pub mod fold;
pub mod sse;
mod stream;

use std::collections::BTreeMap;

use buffa_types::google::protobuf::Struct;
use serde_json::{Map, Value, json};
use url::Url;

pub use codegen::agents::AgentClient;
pub use codegen::error::{ApiError, Error, Result};
pub use codegen::hosts::HostClient;
pub use codegen::sessions::SessionClient;
pub use codegen::transport::HttpClient;
pub use events::{ElicitationRequest, Event, OutputItem, ResponseStatus, Role};
pub use fold::{Approval, Conversation, Message, Part, ToolCall, ToolName, ToolState};
pub use models::omnigent::v1 as api;
pub use stream::EventStream;

/// An Omnigent server: the generated per-service clients, plus the session stream and
/// helpers that build the untyped event bodies.
#[derive(Clone, Debug)]
pub struct OmnigentClient {
    http: HttpClient,
    base_url: Url,
    sessions: SessionClient,
    agents: AgentClient,
    hosts: HostClient,
}

impl std::fmt::Debug for SessionClient {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SessionClient")
            .field("base_url", &self.base_url)
            .finish()
    }
}

impl std::fmt::Debug for AgentClient {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("AgentClient")
            .field("base_url", &self.base_url)
            .finish()
    }
}

impl std::fmt::Debug for HostClient {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("HostClient")
            .field("base_url", &self.base_url)
            .finish()
    }
}

/// The answer to an elicitation ([`OmnigentClient::resolve_elicitation`]).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ElicitationAction {
    /// Approve, or submit the form.
    Accept,
    /// Reject.
    Decline,
    /// Dismiss without an answer.
    Cancel,
}

impl ElicitationAction {
    /// The wire value: `accept`, `decline` or `cancel`.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Accept => "accept",
            Self::Decline => "decline",
            Self::Cancel => "cancel",
        }
    }
}

impl OmnigentClient {
    /// A client of the server at `base_url` over `http`. A gateway prefix in `base_url` is
    /// kept (`http://localhost:8080/omnigent` → `…/omnigent/v1/sessions`).
    pub fn new(http: reqwest::Client, base_url: Url) -> Self {
        Self::with_transport(HttpClient::new(http), base_url)
    }

    /// A client over a configured transport (a bearer token, a `User-Agent`).
    pub fn with_transport(http: HttpClient, mut base_url: Url) -> Self {
        if !base_url.path().ends_with('/') {
            base_url.set_path(&format!("{}/", base_url.path()));
        }
        Self {
            sessions: SessionClient::new(http.clone(), base_url.clone()),
            agents: AgentClient::new(http.clone(), base_url.clone()),
            hosts: HostClient::new(http.clone(), base_url.clone()),
            http,
            base_url,
        }
    }

    /// The server's root, ending in `/`.
    pub fn base_url(&self) -> &Url {
        &self.base_url
    }

    /// `/v1/sessions`: the generated calls.
    pub fn sessions(&self) -> &SessionClient {
        &self.sessions
    }

    /// `/v1/agents`.
    pub fn agents(&self) -> &AgentClient {
        &self.agents
    }

    /// `/v1/hosts`.
    pub fn hosts(&self) -> &HostClient {
        &self.hosts
    }

    /// Create a session of the agent `agent_id`; `configure` sets the other fields (title,
    /// host, workspace, ...).
    pub async fn create_session(
        &self,
        agent_id: &str,
        configure: impl FnOnce(&mut api::CreateSessionRequest),
    ) -> Result<api::Session> {
        let mut request = api::CreateSessionRequest {
            agent_id: agent_id.to_owned(),
            ..Default::default()
        };
        configure(&mut request);
        self.sessions.create_session(&request).await
    }

    /// The session's snapshot with its history (`include_items`), what a reconnecting
    /// stream resyncs from ([`Conversation::from_session`]).
    pub async fn snapshot(&self, session_id: &str) -> Result<api::Session> {
        self.sessions
            .get_session(&api::GetSessionRequest {
                session_id: session_id.to_owned(),
                include_items: Some(true),
                ..Default::default()
            })
            .await
    }

    /// Every session whose labels include all of `labels` (top-level and sub-agent
    /// sessions; archived ones with `include_archived`), newest first.
    ///
    /// Omnigent has no label filter on `GET /v1/sessions` (v0.23), so this pages through
    /// the caller's sessions and filters here: a scan, as cheap as the caller's session
    /// count. It is how a caller finds the session it created for something
    /// (`factory.node=…`) again, e.g. after a restart.
    pub async fn find_sessions(
        &self,
        labels: &BTreeMap<String, String>,
        include_archived: bool,
    ) -> Result<Vec<api::SessionListItem>> {
        let mut found = Vec::new();
        let mut after = None;
        loop {
            let page = self
                .sessions
                .list_sessions(&api::ListSessionsRequest {
                    limit: Some(LIST_LIMIT),
                    after: after.take(),
                    include_archived: Some(include_archived),
                    kind: Some("any".into()),
                    ..Default::default()
                })
                .await?;
            let last = page.data.last().map(|s| s.id.clone());
            found.extend(page.data.into_iter().filter(|session| {
                labels
                    .iter()
                    .all(|(k, v)| session.labels.get(k).is_some_and(|have| have == v))
            }));
            match (page.has_more, page.last_id.or(last)) {
                (true, Some(last)) => after = Some(last),
                _ => return Ok(found),
            }
        }
    }

    /// The pull requests linked to the session, all pages, and whether the server has
    /// imported them from the forge yet (`synced`). Until it has, an empty list means
    /// "not known yet", not "none".
    pub async fn pull_requests(&self, session_id: &str) -> Result<(Vec<api::PullRequest>, bool)> {
        let mut found = Vec::new();
        let mut after = None;
        loop {
            let page = self
                .sessions
                .list_pull_requests(&api::ListPullRequestsRequest {
                    session_id: session_id.to_owned(),
                    limit: Some(PULL_REQUESTS_LIMIT),
                    after: after.take(),
                    ..Default::default()
                })
                .await?;
            found.extend(page.data);
            match (page.has_more, page.last_id) {
                (true, Some(last)) => after = Some(last),
                _ => return Ok((found, page.synced)),
            }
        }
    }

    /// Post an event of type `kind` with the payload `data` to the session.
    pub async fn post_event(
        &self,
        session_id: &str,
        kind: &str,
        data: Map<String, Value>,
    ) -> Result<api::EventAck> {
        let request = api::PostEventRequest {
            session_id: session_id.to_owned(),
            event_type: kind.to_owned(),
            data: to_struct(data)?.into(),
            ..Default::default()
        };
        self.sessions.post_event(&request).await
    }

    /// Send a user message: starts a turn, or queues behind the running one.
    pub async fn send_message(&self, session_id: &str, text: &str) -> Result<api::EventAck> {
        let data = json!({
            "role": "user",
            "content": [{"type": "input_text", "text": text}],
        });
        self.post_event(session_id, "message", into_map(data)).await
    }

    /// Interrupt the running turn.
    pub async fn interrupt(&self, session_id: &str) -> Result<api::EventAck> {
        self.post_event(session_id, "interrupt", Map::new()).await
    }

    /// Answer a client-side tool call (`runtime: client`) with its result.
    pub async fn send_function_call_output(
        &self,
        session_id: &str,
        call_id: &str,
        output: &str,
    ) -> Result<api::EventAck> {
        let data = json!({"call_id": call_id, "output": output});
        self.post_event(session_id, "function_call_output", into_map(data))
            .await
    }

    /// Answer a `response.elicitation_request`: an approval, or a form's values (`content`,
    /// with [`ElicitationAction::Accept`]).
    pub async fn resolve_elicitation(
        &self,
        session_id: &str,
        elicitation_id: &str,
        action: ElicitationAction,
        content: Option<Map<String, Value>>,
    ) -> Result<api::EventAck> {
        let request = api::ResolveElicitationRequest {
            session_id: session_id.to_owned(),
            elicitation_id: elicitation_id.to_owned(),
            action: action.as_str().to_owned(),
            content: content.map(to_struct).transpose()?.into(),
            ..Default::default()
        };
        self.sessions.resolve_elicitation(&request).await
    }

    /// Open the session's event stream (`GET /v1/sessions/{id}/stream`, SSE). Resolves once
    /// the server has answered, so events posted afterwards are seen. There is no replay:
    /// events from before the call are only in [`Self::snapshot`].
    pub async fn stream(&self, session_id: &str) -> Result<EventStream> {
        stream::open(&self.http, &self.base_url, session_id).await
    }
}

/// The largest page `GET /v1/sessions` serves.
const LIST_LIMIT: i32 = 1000;
/// The largest page `GET /v1/sessions/{id}/pull-requests` serves.
const PULL_REQUESTS_LIMIT: i32 = 100;

/// A JSON object as a `google.protobuf.Struct`.
pub fn to_struct(map: Map<String, Value>) -> Result<Struct> {
    Ok(serde_json::from_value(Value::Object(map))?)
}

/// A `google.protobuf.Struct` as a JSON object.
pub fn from_struct(value: &Struct) -> Map<String, Value> {
    match serde_json::to_value(value) {
        Ok(Value::Object(map)) => map,
        _ => Map::new(),
    }
}

fn into_map(value: Value) -> Map<String, Value> {
    match value {
        Value::Object(map) => map,
        _ => Map::new(),
    }
}
